:where(.ds-theme-example) button { box-sizing: border-box; border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }
:where(.ds-theme-example) button:focus-visible { position: relative; z-index: 1; outline: 2px solid var(--focus, #2450a7); outline-offset: 3px; }
.ds-icon-button { display: inline-flex; min-width: 44px; min-height: 44px; align-items: center; justify-content: center; gap: 0.35rem; padding-inline: 0.5rem; border-radius: 8px; color: var(--ink, #262031); font-size: 0.8125rem; font-weight: 650; }
.ds-icon-button:hover, .ds-quiet-button:not([aria-disabled="true"]):hover { background: var(--tile-hover, #f2e3c8); }

.ds-settings-example { font-family: system-ui, -apple-system, 'Segoe UI', sans-serif; color: var(--ink, #262031); background: var(--paper, #fbf2de); }
:where(.ds-settings-example) button { box-sizing: border-box; border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }
:where(.ds-settings-example) button:focus-visible { position: relative; z-index: 1; outline: 2px solid var(--focus, #2450a7); outline-offset: 3px; }
.ds-segments { display: flex; align-items: center; gap: 0.125rem; min-width: 0; margin: 0; padding: 0; border: 0; }
.ds-segments button { min-height: 44px; padding: 0.3rem 0.65rem; border-radius: 7px; color: var(--muted, #645752); font-size: 0.875rem; font-weight: 700; white-space: nowrap; }
.ds-segments button:hover { background: var(--tile-hover, #f2e3c8); color: var(--ink, #262031); }
.ds-segments button[aria-pressed="true"] { background: var(--ink, #262031); color: var(--active-text, #fbf2de); }

.ds-game { font-family: system-ui, -apple-system, 'Segoe UI', sans-serif; color: var(--ink, #262031); background: var(--paper, #fbf2de); }.ds-game [data-player="one"] { --player-ink: var(--red, #9a2f3e); --player-tint: var(--red-tint, #f8d7d6); --sticker-angle: -7deg; }.ds-game [data-player="two"] { --player-ink: var(--blue, #2450a7); --player-tint: var(--blue-tint, #dce7ff); --sticker-angle: 6deg; }
:where(.ds-game) button { box-sizing: border-box; border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }
:where(.ds-game) button:focus-visible { position: relative; z-index: 1; outline: 2px solid var(--focus, #2450a7); outline-offset: 3px; }
.ds-game :where(h2, p) { margin: 0; }
.ds-scoreboard {
  --score-sticker-size: clamp(2.75rem, 12vw, 3.75rem);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: start;
  gap: clamp(0.3rem, 2vw, 0.8rem);
  padding-block: 0.65rem;
  border-bottom: 1px solid var(--rule, #b9a587);
}

.ds-player {
  display: grid;
  grid-template-columns: var(--score-sticker-size) minmax(0, 1fr);
  align-items: start;
  gap: clamp(0.3rem, 2vw, 0.75rem);
  min-width: 0;
}

.ds-player[data-player="two"] {
  grid-template-columns: minmax(0, 1fr) var(--score-sticker-size);
  text-align: right;
}

.ds-score-sticker {
  display: grid;
  flex: none;
  width: var(--score-sticker-size);
  aspect-ratio: 1;
  place-items: center;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 13px;
  background: var(--player-tint);
  color: var(--player-ink);
  font-family: var(--emoji-font, "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif);
  font-size: clamp(1.45rem, 6vw, 2.1rem);
  line-height: 1;
}

.ds-score-sticker .ds-emoji,
.ds-robot-sticker {
  rotate: var(--sticker-angle);
}

.ds-robot-sticker {
  grid-area: 1 / 2;
}

.ds-player[data-active="true"] .ds-score-sticker,
.ds-sticker-trigger:hover .ds-score-sticker {
  border-color: var(--player-ink);
}

.ds-sticker-trigger {
  display: grid;
  grid-area: 1 / 1 / 2 / -1;
  justify-items: start;
  gap: 0.25rem;
  padding: 0;
  border-radius: 8px;
}

.ds-player[data-player="two"] .ds-sticker-trigger {
  justify-items: end;
}

.ds-sticker-label {
  color: var(--player-ink);
  font-size: 0.6875rem;
  font-weight: 650;
  line-height: 1.15;
  text-decoration: underline;
  text-underline-offset: 0.14em;
}

.ds-player-tally,
.ds-draws {
  display: grid;
  min-height: var(--score-sticker-size);
  align-content: center;
  gap: 0.1rem;
  color: var(--muted, #645752);
  font-size: clamp(0.69rem, 2.95vw, 0.8125rem);
  font-weight: 650;
  line-height: 1.2;
}

.ds-player-tally {
  grid-area: 1 / 2;
  overflow-wrap: anywhere;
  pointer-events: none;
}

.ds-player[data-player="two"] .ds-player-tally {
  grid-column: 1;
}

.ds-player-tally strong,
.ds-draws strong {
  color: var(--ink, #262031);
  font-family: "Barlow Condensed", "Arial Narrow", sans-serif;
  font-size: clamp(1.55rem, 7vw, 2.1rem);
  font-variant-numeric: tabular-nums;
  line-height: 0.95;
}

.ds-player[data-active="true"] .ds-player-tally,
.ds-player[data-active="true"] .ds-player-tally strong {
  color: var(--player-ink);
}

.ds-draws {
  min-width: 3.3rem;
  justify-items: center;
  padding: 0.25rem;
  border-radius: 7px;
}

.ds-draws[data-draw="true"],
.ds-draws[data-draw="true"] strong {
  background: var(--draw-tint, #fae8ae);
  color: var(--draw, #725414);
}

.ds-player[data-scored] .ds-player-tally strong,
.ds-draws[data-draw="true"] strong {
  animation: score-tick 260ms 160ms cubic-bezier(0.16, 1, 0.3, 1);
}

.ds-mark,
.ds-preview,
.ds-emoji {
  font-family: var(--emoji-font, "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif);
  line-height: 1;
}

@keyframes score-tick {
  45% { transform: translateY(-0.13em) scale(1.16); }
}

@media (max-width: 350px) {

  .ds-draws {
    min-width: 2.25rem;
  }
}

@media (max-width: 420px) and (max-height: 650px) {

  .ds-scoreboard {
    padding-block: 0.25rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-mark,
  .ds-square[data-winning] .ds-mark,
  .ds-player[data-scored] .ds-player-tally strong,
  .ds-draws[data-draw="true"] strong {
    animation: none;
    transition: none;
  }
}

.ds-game { font-family: system-ui, -apple-system, 'Segoe UI', sans-serif; color: var(--ink, #262031); background: var(--paper, #fbf2de); }
:where(.ds-game) button { box-sizing: border-box; border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }
:where(.ds-game) button:focus-visible { position: relative; z-index: 1; outline: 2px solid var(--focus, #2450a7); outline-offset: 3px; }
.ds-game :where(h2, p) { margin: 0; }

.ds-game [data-player="one"] {
  --player-ink: var(--red, #9a2f3e);
  --player-tint: var(--red-tint, #f8d7d6);
  --sticker-angle: -7deg;
}

.ds-game [data-player="two"] {
  --player-ink: var(--blue, #2450a7);
  --player-tint: var(--blue-tint, #dce7ff);
  --sticker-angle: 6deg;
}

.ds-turn {
  display: flex;
  min-height: 3.25rem;
  align-items: center;
  justify-content: center;
  margin-block: 0.25rem;
  padding: 0.25rem 0.5rem;
  border: 2px solid transparent;
  border-radius: 9px;
  font-size: 0.9375rem;
  font-weight: 750;
  text-align: center;
}

.ds-turn[data-outcome] {
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.125rem 0.125rem 0.125rem 0.65rem;
  text-align: left;
}

.ds-turn[data-outcome="win"] {
  background: var(--player-tint);
  color: var(--player-ink);
}

.ds-turn[data-outcome="draw"] {
  background: var(--draw-tint, #fae8ae);
  color: var(--draw, #725414);
}

.ds-board {
  container-type: inline-size;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(0.3rem, 1.4vw, 0.5rem);
  padding: clamp(0.3rem, 1.4vw, 0.5rem);
  border: 2px solid var(--ink, #262031);
  border-radius: 15px;
  background: var(--grid, #dfcdb1);
}

.ds-square {
  position: relative;
  display: grid;
  aspect-ratio: 1;
  min-width: 0;
  place-items: center;
  padding: 0;
  border: 1px solid var(--tile-edge, #917c67);
  border-radius: 9px;
  background: var(--tile, #fffaf0);
  line-height: 1;
}

.ds-square[aria-disabled="false"]:active {
  background: var(--tile-hover, #f2e3c8);
}

.ds-square:focus-visible {
  outline-offset: -4px;
}

.ds-square[data-player] {
  border-color: var(--player-ink);
  background: var(--player-tint);
}

.ds-square[data-last-move]::after {
  position: absolute;
  inset-block-start: 0.45rem;
  inset-inline-end: 0.45rem;
  width: 0.375rem;
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--player-ink);
  content: "";
}

.ds-square[data-winning] {
  border-width: 2px;
  background: color-mix(in srgb, var(--player-tint) 88%, var(--player-ink));
}

.ds-mark,
.ds-preview,
.ds-emoji {
  font-family: var(--emoji-font, "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif);
  line-height: 1;
}

.ds-mark,
.ds-preview {
  display: block;
  font-size: clamp(1.6rem, 15cqi, 4.5rem);
  rotate: var(--sticker-angle);
}

.ds-preview {
  pointer-events: none;
  opacity: 0;
  transition: opacity 100ms ease-out;
}

.ds-square:focus-visible .ds-preview {
  opacity: 0.42;
}

@media (hover: hover) and (pointer: fine) {
  .ds-square[aria-disabled="false"]:hover {
    background: var(--tile-hover, #f2e3c8);
    border-color: var(--ink, #262031);
  }

  .ds-square:hover .ds-preview {
    opacity: 0.42;
    transition-delay: 60ms;
  }

  .ds-square:active .ds-preview {
    opacity: 0.6;
    transition-delay: 0ms;
  }
}

.ds-mark {
  filter: drop-shadow(0 2px 0 var(--sticker-edge, #fffdf6)) drop-shadow(0 -1px 0 var(--sticker-edge, #fffdf6));
  animation: place-mark 180ms cubic-bezier(0.16, 1, 0.3, 1);
  transition: scale 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.ds-board[data-won] .ds-square:not([data-winning]) .ds-mark {
  scale: 0.78;
}

.ds-square[data-winning] .ds-mark {
  --win-entrance: 380ms;
  scale: 1.26;
  animation:
    win-mark var(--win-entrance) cubic-bezier(0.16, 1, 0.3, 1) backwards,
    win-tilt 3s ease-in-out infinite;
  transition: none;
}

.ds-board[data-tilt-paused] .ds-square[data-winning] .ds-mark {
  animation-play-state: running, paused;
}

@keyframes place-mark {
  from { transform: scale(0.82) rotate(calc(-1 * var(--sticker-angle))); }
  to { transform: none; }
}

@keyframes win-mark {
  0% { transform: scale(0.79); }
  52% { transform: scale(1.08) rotate(var(--sticker-angle)); }
  100% { transform: none; }
}

@keyframes win-tilt {
  0%, 22%, 100% { transform: none; }
  5% { transform: rotate(-10deg); }
  11% { transform: rotate(10deg); }
  17% { transform: rotate(-5deg); }
}

.ds-quiet-button,
.ds-play-again {
  min-height: 44px;
  padding: 0.38rem 0.65rem;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 700;
}

.ds-play-again {
  min-width: 7.1rem;
  background: var(--ink, #262031);
  color: var(--active-text, var(--paper));
}

.ds-play-again:hover {
  text-decoration: underline;
