}

@media (max-width: 420px) and (max-height: 650px) {

  .ds-turn {
    min-height: 44px;
    margin-block: 0.125rem;
    padding-block: 0;
    border: 0;
  }

  .ds-board {
    width: min(100%, max(15rem, calc(100dvh - 17rem)));
    margin-inline: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-mark,
  .ds-square[data-winning] .ds-mark,
  .ds-player[data-scored] .ds-player-tally strong,
  .ds-draws[data-draw="true"] strong {
    animation: none;
    transition: none;
  }

  .ds-preview {
    transition: none;
  }
}

